function updateLastActivity(ss) {
  try {
    const urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) return;
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        if (keys[i][0] === 'ULTIMA_ACTIVIDAD') {
          urlSheet.getRange(i + 2, 2).setValue(new Date().toLocaleString());
          return;
        }
      }
    }
    urlSheet.appendRow(['ULTIMA_ACTIVIDAD', new Date().toLocaleString(), 'Última acción']);
  } catch (e) {}
}

