/**
 * Obtiene la tasa del BCV almacenada en la pestaña 'URL',
 * buscando en la Columna A la clave 'Tasa BCV' y leyendo su valor en la Columna B.
 */
function getBcvRateFromSheet(ss) {
  try {
    const urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) return 54.50;
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const data = urlSheet.getRange(2, 1, lastRow - 1, 2).getValues();
      for (var i = 0; i < data.length; i++) {
        var key = String(data[i][0]).trim();
        if (key === 'Tasa BCV' || key.toLowerCase() === 'tasa bcv' || key.toUpperCase() === 'TASA_BCV') {
          var val = Number(data[i][1]);
          if (!isNaN(val) && val > 0) {
            return val;
          }
        }
      }
    }
    return 54.50;
  } catch (e) {
    return 54.50;
  }
}

/**
 * Guarda o actualiza la tasa del BCV en la pestaña 'URL':
 * Columna A: "Tasa BCV", Columna B: valor numérico de la tasa.
 */
function setBcvRateInSheet(ss, rate) {
  try {
    let urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) {
      urlSheet = ss.insertSheet(SHEET_NAMES.URL);
      const headers = ['CLAVE', 'VALOR', 'DESCRIPCION'];
      urlSheet.appendRow(headers);
      styleHeaderRow(urlSheet, headers);
    }
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        var key = String(keys[i][0]).trim();
        if (key === 'Tasa BCV' || key.toLowerCase() === 'tasa bcv' || key.toUpperCase() === 'TASA_BCV') {
          urlSheet.getRange(i + 2, 1).setValue('Tasa BCV');
          urlSheet.getRange(i + 2, 2).setValue(rate);
          return;
        }
      }
    }
    urlSheet.appendRow(['Tasa BCV', rate, 'Tasa oficial BCV (Bs. por USD)']);
  } catch (e) {}
}

/**
 * Asegura que la fila 'Tasa BCV' exista en la hoja URL
 */
function ensureBcvRowInUrlSheet(urlSheet) {
  try {
    const lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      const keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        var key = String(keys[i][0]).trim();
        if (key === 'Tasa BCV' || key.toLowerCase() === 'tasa bcv' || key.toUpperCase() === 'TASA_BCV') {
          return;
        }
      }
    }
    urlSheet.appendRow(['Tasa BCV', 54.50, 'Tasa oficial BCV (Bs. por USD)']);
  } catch (e) {}
}

/**
 * Obtiene el nombre y teléfono del restaurante guardados en la hoja 'URL':
 * Columna A: "RESTAURANTE" -> Columna B: Nombre del restaurante
 * Columna A: "TELEFONO" -> Columna B: Teléfono de contacto
 */
function getRestaurantInfoFromSheet(ss) {
  var info = {
    name: 'ComandaPro Restaurante',
    phone: '+58 412 1234567'
  };
  try {
    var urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) return info;
    var lastRow = urlSheet.getLastRow();
    if (lastRow > 1) {
      var data = urlSheet.getRange(2, 1, lastRow - 1, 2).getValues();
      for (var i = 0; i < data.length; i++) {
        var key = String(data[i][0]).trim().toUpperCase();
        var val = String(data[i][1] != null ? data[i][1] : '').trim();
        if ((key === 'RESTAURANTE' || key === 'NOMBRE_SISTEMA') && val) {
          info.name = val;
        } else if ((key === 'TELEFONO' || key === 'TELÉFONO' || key === 'TELEFONO_RESTAURANTE') && val) {
          info.phone = val;
        }
      }
    }
    return info;
  } catch (e) {
    return info;
  }
}

/**
 * Guarda o actualiza 'RESTAURANTE' y 'TELEFONO' en la hoja 'URL':
 * Columna A: "RESTAURANTE", Columna B: Nombre del restaurante
 * Columna A: "TELEFONO", Columna B: Teléfono del restaurante
 */
function setRestaurantInfoInSheet(ss, name, phone) {
  try {
    var urlSheet = ss.getSheetByName(SHEET_NAMES.URL);
    if (!urlSheet) {
      urlSheet = ss.insertSheet(SHEET_NAMES.URL);
      var headers = ['CLAVE', 'VALOR', 'DESCRIPCION'];
      urlSheet.appendRow(headers);
      styleHeaderRow(urlSheet, headers);
    }
    var lastRow = urlSheet.getLastRow();
    var hasRestaurante = false;
    var hasTelefono = false;

    if (lastRow > 1) {
      var keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        var key = String(keys[i][0]).trim().toUpperCase();
        if (key === 'RESTAURANTE' || key === 'NOMBRE_SISTEMA') {
          urlSheet.getRange(i + 2, 1).setValue('RESTAURANTE');
          if (name) urlSheet.getRange(i + 2, 2).setValue(name);
          hasRestaurante = true;
        }
        if (key === 'TELEFONO' || key === 'TELÉFONO' || key === 'TELEFONO_RESTAURANTE') {
          urlSheet.getRange(i + 2, 1).setValue('TELEFONO');
          if (phone) urlSheet.getRange(i + 2, 2).setValue(phone);
          hasTelefono = true;
        }
      }
    }

    if (!hasRestaurante && name) {
      urlSheet.appendRow(['RESTAURANTE', name, 'Nombre del restaurante']);
    }
    if (!hasTelefono && phone) {
      urlSheet.appendRow(['TELEFONO', phone, 'Teléfono de contacto del restaurante']);
    }
  } catch (e) {}
}

/**
 * Asegura que las filas 'RESTAURANTE' y 'TELEFONO' existan en la hoja URL
 */
function ensureRestaurantRowsInUrlSheet(urlSheet) {
  try {
    var lastRow = urlSheet.getLastRow();
    var hasRestaurante = false;
    var hasTelefono = false;
    if (lastRow > 1) {
      var keys = urlSheet.getRange(2, 1, lastRow - 1, 1).getValues();
      for (var i = 0; i < keys.length; i++) {
        var key = String(keys[i][0]).trim().toUpperCase();
        if (key === 'RESTAURANTE' || key === 'NOMBRE_SISTEMA') hasRestaurante = true;
        if (key === 'TELEFONO' || key === 'TELÉFONO') hasTelefono = true;
      }
    }
    if (!hasRestaurante) {
      urlSheet.appendRow(['RESTAURANTE', 'ComandaPro Restaurante', 'Nombre del restaurante']);
    }
    if (!hasTelefono) {
      urlSheet.appendRow(['TELEFONO', '+58 412 1234567', 'Teléfono de contacto del restaurante']);
    }
  } catch (e) {}
}

/**
 * Actualiza la columna H (PRECIO_BS) de todos los platos en la pestaña PLATOS
 * multiplicando el precio en USD por la nueva tasa BCV.
 */
function updateAllDishPricesInSheet(ss, rate) {
  try {
    const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
    if (!sheet) return;
    const lastRow = sheet.getLastRow();
    if (lastRow > 1) {
      const prices = sheet.getRange(2, 4, lastRow - 1, 1).getValues();
      const bsValues = [];
      for (var i = 0; i < prices.length; i++) {
        var priceUsd = Number(prices[i][0]) || 0;
        bsValues.push([Number((priceUsd * rate).toFixed(2))]);
      }
      sheet.getRange(2, 8, lastRow - 1, 1).setValues(bsValues);
    }
  } catch (e) {}
}

// =========================================================================
// LECTURA DE DATOS PARA SINCRONIZACIÓN EN VIVO (doGet)
// =========================================================================

function getTablesFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  const rows = sheet.getRange(2, 1, lastRow - 1, 8).getValues();
  return rows.map(function(r) {
    return {
      id: String(r[0]),
      name: String(r[1]),
      capacity: Number(r[2]) || 4,
      status: String(r[3]) || 'libre',
      occupiedByWaiterId: r[4] ? String(r[4]) : undefined,
      occupiedByWaiterName: r[5] ? String(r[5]) : undefined,
      currentOrderId: r[6] ? String(r[6]) : undefined,
      occupiedSince: r[7] ? String(r[7]) : undefined
    };
  });
}

function getMenuFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.PLATOS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  const lastCol = Math.max(sheet.getLastColumn(), 9);
  const rows = sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
  return rows.map(function(r) {
    var photoUrl = '';
    if (r[8] && String(r[8]).trim() !== '') {
      photoUrl = String(r[8]).trim();
    } else if (r[7] && String(r[7]).startsWith('http')) {
      photoUrl = String(r[7]).trim();
    }

    return {
      id: String(r[0]),
      name: String(r[1]),
      category: String(r[2]),
      price: Number(r[3]) || 0,
      description: String(r[4] || ''),
      available: String(r[5]).toUpperCase() !== 'NO',
      preparationTimeMinutes: Number(r[6]) || 10,
      image: photoUrl || undefined
    };
  });
}

function getUsersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  // Read up to 6 columns: ID, NOMBRE, ROL, ACTIVO, USUARIO, PASSWORD
  const numCols = Math.min(sheet.getLastColumn(), 6);
  const rows = sheet.getRange(2, 1, lastRow - 1, numCols).getValues();
  return rows.map(function(r) {
    const name = String(r[1] || '');
    const defaultUsername = name.toLowerCase().replace(/s+/g, '');
    return {
      id: String(r[0]),
      name: name,
      role: String(r[2] || 'mesonero'),
      active: String(r[3] || 'SI').toUpperCase() !== 'NO',
      username: r[4] ? String(r[4]).trim() : defaultUsername,
      password: r[5] ? String(r[5]).trim() : '123'
    };
  });
}

function getOrdersFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.ORDENES);
  const activeOrders = {};
  const kitchenTickets = [];

  if (!sheet) return { activeOrders, kitchenTickets };
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return { activeOrders, kitchenTickets };

  const rows = sheet.getRange(2, 1, lastRow - 1, 10).getValues();

  for (var i = 0; i < rows.length; i++) {
    const r = rows[i];
    const orderId = String(r[0]);
    const status = String(r[5]);

    // Ignorar órdenes ya cobradas o canceladas
    if (status === 'cobrada' || status === 'cancelada') continue;

    var items = [];
    try {
      items = JSON.parse(r[7] || '[]');
    } catch(e) {
      items = [];
    }

    // NUNCA generar tickets ni órdenes activas sin platos
    if (!Array.isArray(items) || items.length === 0) continue;

    const orderObj = {
      id: orderId,
      orderNumber: String(r[1]),
      tableId: String(r[2]),
      tableName: String(r[3]),
      waiterName: String(r[4]),
      waiterId: '',
      status: status,
      currentRound: Number(r[6]) || 1,
      totalRounds: Number(r[6]) || 1,
      items: items,
      createdAt: String(r[8]),
      updatedAt: String(r[9])
    };

    activeOrders[orderId] = orderObj;

    // Crear tickets de cocina ÚNICAMENTE si hay platos y la comanda fue enviada a cocina
    if (items.length > 0 && (status === 'en_cocina' || status === 'preparando' || status === 'listo')) {
      var ticketStatus = 'en_cola';
      if (status === 'preparando') ticketStatus = 'preparando';
      if (status === 'listo') ticketStatus = 'listo';

      kitchenTickets.push({
        id: 'kt-' + orderId,
        orderId: orderId,
        orderNumber: orderObj.orderNumber,
        tableId: orderObj.tableId,
        tableName: orderObj.tableName,
        waiterName: orderObj.waiterName,
        roundNumber: orderObj.currentRound,
        isAdditional: orderObj.currentRound > 1,
        createdAt: orderObj.createdAt,
        status: ticketStatus,
        items: items
      });
    }
  }

  return { activeOrders, kitchenTickets };
}

function getPaymentsFromSheet(ss) {
  const sheet = ss.getSheetByName(SHEET_NAMES.VENTAS);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return [];

  // Traer los últimos 50 cobros
  const startRow = Math.max(2, lastRow - 49);
  const numRows = lastRow - startRow + 1;
  const rows = sheet.getRange(startRow, 1, numRows, 11).getValues();

  return rows.reverse().map(function(r) {
    return {
      FECHA_PAGO: String(r[0]),
      NUMERO_PEDIDO: String(r[1]),
      MESA: String(r[2]),
      MESONERO: String(r[3]),
      SUBTOTAL: Number(r[4]) || 0,
      IMPUESTOS: Number(r[5]) || 0,
      PROPINA: Number(r[6]) || 0,
      TOTAL: Number(r[7]) || 0,
      METODO_PAGO: String(r[8]),
      REFERENCIA: String(r[9]),
      ITEMS_CONSUMIDOS: String(r[10]),
      syncedToSheet: true
    };
  });
}

